   [185]={next_id=186, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="听到这句话，梅德洛丝好像松了口气。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_607.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [186]={next_id=187, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="其实在公审前，妈妈和爸爸都以为我死掉了，他们当初仓皇地带着全家一起率先逃离，然后又在拉蒂夫家族的命令下，作为先遣队归来。", msg_color="", msg_size=0, talker="梅德洛丝", audio="", img="arts/ui/bg/story/storybg_607.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4527", 0, 0, 28.5, 221}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [187]={next_id=188, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我无意否认他们在灾难中的功劳，但身为城镇的管理者，理应一起接受公众的审判。", msg_color="", msg_size=0, talker="梅德洛丝", audio="", img="arts/ui/bg/story/storybg_607.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4527", 0, 0, 28.5, 221}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
